from flask import Flask, request, jsonify
import lxml.etree as etree
import io
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

# Configuration for document processing service
MAX_DOCUMENT_SIZE = 10 * 1024 * 1024  # 10MB
ALLOWED_CONTENT_TYPES = ['application/xml', 'text/xml', 'application/soap+xml']

def validate_content_type(content_type):
    """Check if the content type is in our allowed list."""
    if not content_type:
        return False
    base_type = content_type.split(';')[0].strip().lower()
    return base_type in ALLOWED_CONTENT_TYPES

def parse_xml_document(xml_data):
    """Parse XML document and extract structured data.
    Uses lxml for performance with large documents.
    """
    try:
        parser = etree.XMLParser(
            resolve_entities=True,
            no_network=False,
            dtd_validation=False,
            load_dtd=True
        )
        tree = etree.parse(io.BytesIO(xml_data), parser)
        root = tree.getroot()

        # Extract document metadata
        result = {
            'root_tag': root.tag,
            'attributes': dict(root.attrib),
            'children': []
        }

        for child in root:
            child_data = {
                'tag': child.tag,
                'text': child.text if child.text else '',
                'attributes': dict(child.attrib)
            }
            result['children'].append(child_data)

        return result, None
    except etree.XMLSyntaxError as e:
        return None, f"XML syntax error: {str(e)}"
    except Exception as e:
        logger.error(f"Unexpected error parsing XML: {str(e)}")
        return None, f"Processing error: {str(e)}"

@app.route('/api/v1/documents/parse', methods=['POST'])
def parse_document():
    """Endpoint to parse and extract data from XML documents.
    Used by internal microservices for document processing pipeline.
    """
    # Validate content type
    if not validate_content_type(request.content_type):
        return jsonify({'error': 'Unsupported content type', 
                       'allowed': ALLOWED_CONTENT_TYPES}), 415

    # Check document size
    xml_data = request.get_data()
    if len(xml_data) > MAX_DOCUMENT_SIZE:
        return jsonify({'error': 'Document exceeds maximum size'}), 413

    if not xml_data:
        return jsonify({'error': 'Empty request body'}), 400

    # Parse the document
    result, error = parse_xml_document(xml_data)

    if error:
        return jsonify({'error': error}), 422

    return jsonify({
        'status': 'success',
        'document': result
    }), 200

@app.route('/api/v1/documents/validate', methods=['POST'])
def validate_document():
    """Validate XML document structure without full parsing."""
    xml_data = request.get_data()
    if not xml_data:
        return jsonify({'error': 'Empty request body'}), 400

    try:
        etree.fromstring(xml_data)
        return jsonify({'valid': True}), 200
    except etree.XMLSyntaxError as e:
        return jsonify({'valid': False, 'reason': str(e)}), 200

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
